/**
 * Gradient waves shader.
 *
 * ## The mathematical idea
 *
 * A gradient repeated in horizontal bands — background, first hue, second
 * hue, background — whose height is displaced by a swell. The swell is a
 * sum of sines of the abscissa, at non-multiple frequencies and opposite
 * speeds, so that it never closes back on itself.
 *
 * What sets these waves apart from rippling lines or from slices: there is
 * neither stroke nor step, only sheets of colour sliding over one another.
 * The softness sets the width of the transitions: low, the bands are clean;
 * high, they melt into a single gradient that
 * ripples.
 *
 * ## Uniforms
 *
 * - `uTime` — time in seconds, supplied by the engine.
 * - `uResolution` — canvas size in pixels, supplied by the engine.
 * - `uColorA` — the background.
 * - `uColorB` — the first hue of the bands.
 * - `uColorC` — the second hue of the bands.
 * - `uBands` — number of bands across the height.
 * - `uAmplitude` — height of the swell, as a fraction of the frame.
 * - `uSpeed` — speed of the swell.
 * - `uSoftness` — width of the transitions.
 * - `uDetail` — number of harmonics in the swell, and so its cost.
 */
export const GRADIENT_WAVES_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uBands;
uniform float uAmplitude;
uniform float uSpeed;
uniform float uSoftness;
uniform float uDetail;

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float x = vUv.x * aspect;
  float t = uTime * uSpeed;
  int harmonics = int(clamp(uDetail, 1.0, 3.0));

  // The swell: sines at non-multiple frequencies, at opposite speeds.
  float swell = sin(x * 2.4 + t);
  if (harmonics >= 2) swell += 0.5 * sin(x * 4.1 - t * 1.3 + 1.0);
  if (harmonics >= 3) swell += 0.25 * sin(x * 7.3 + t * 0.7 + 2.0);
  swell *= uAmplitude;

  // The band: the displaced height, and a slow drift upwards.
  float phase = (vUv.y + swell) * max(uBands, 0.5) - uTime * 0.05;
  float w = fract(phase);

  // The repeated gradient: the background at 0, the first hue at a third,
  // the second at two thirds, the background at 1. The softness widens them.
  float softness = mix(0.06, 0.33, clamp(uSoftness, 0.0, 1.0));
  float kB = smoothstep(0.333 - softness, 0.333, w) * smoothstep(0.666, 0.666 - softness, w);
  float kC = smoothstep(0.666 - softness, 0.666, w) * smoothstep(1.0, 1.0 - softness, w);

  vec3 colour = mix(uColorA, uColorB, kB);
  colour = mix(colour, uColorC, kC);

  // The crest: where the swell peaks, the band brightens a little.
  float crest = smoothstep(0.0, 1.0, swell / max(uAmplitude * 1.75, 0.0001));
  colour += mix(uColorB, uColorC, 0.5) * crest * 0.12 * max(kB, kC);

  gl_FragColor = vec4(clamp(colour, 0.0, 1.0), 1.0);
}
`

sources.component.tsx:
/**
 * Gradient waves: bands of a repeated gradient, with neither stroke nor step, displaced by a swell that never closes back on itself.
 *
 * ## The principle
 *
 * A gradient repeated in horizontal bands — background, first hue, second
 * hue, background — whose height is displaced by a sum of sines at
 * non-multiple frequencies and opposite speeds. Neither stroke nor step:
 * sheets sliding over one another, and a softness that goes from clean
 * bands to a single rippling gradient.
 *
 * ## What this component delegates
 *
 * It carries only what sets it apart: its shader, its settings and its fallback.
 * Reading the tokens, converting them to floats and re-reading them when the
 * theme changes all come from the engine — copying them here would leave as
 * many versions to maintain as there are backgrounds.
 *
 * The fallback is not a precaution: it is shown while the backend loads, when
 * WebGL is missing, when the arbiter refuses the surface — it grants only one
 * per backend — and under reduced motion.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { GRADIENT_WAVES_FRAGMENT } from './gradient-waves.shader.js'

/** What the escape hatch receives. */
export interface GradientWavesControls {
  /** Colours actually handed to the shader. */
  readonly colours: readonly ShaderColour[]
  /** Reason for the refusal, if there is one. */
  readonly refused: string | undefined
}

/** Properties specific to this component. */
export interface GradientWavesOwnProps {
  /** Number of bands across the height. @defaultValue 4 */
  bands?: number
  /** Height of the swell, as a fraction of the frame. @defaultValue 0.12 */
  amplitude?: number
  /** Speed of the swell. @defaultValue 0.4 */
  speed?: number
  /** Width of the transitions. Low, the bands are clean. @defaultValue 0.6 */
  softness?: number
  /** Tokens whose colours are read. */
  colors?: readonly string[]
  /** Fallback classes. */
  fallback?: string
  /** Escape hatch. */
  onReady?: ReadyCallback<GradientWavesControls>
}

/** Every property. */
export type GradientWavesProps = Customisable<GradientWavesOwnProps>

/** Tokens used by default: the background, the two hues of the bands. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-indigo-400',
  '--o-palette-cyan-300',
] as const

/** Default fallback: a frozen gradient, in the same tones. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-b o-from-zinc-50 dark:o-from-zinc-950 o-via-indigo-200 dark:o-via-indigo-900 o-to-cyan-200 dark:o-to-cyan-900'

/**
 * Detail outside low quality.
 *
 * The number of bands is a frequency, not a loop. It is the harmonics of
 * the swell that are capped.
 */
const DETAIL = 3

/** Detail at low quality. */
const LOW_DETAIL = 1

/**
 * Gradient waves.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <GradientWaves className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function GradientWaves({
  bands = 4,
  amplitude = 0.12,
  speed = 0.4,
  softness = 0.6,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: GradientWavesProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: GRADIENT_WAVES_FRAGMENT,
    colors,
    uniforms: {
      uBands: bands,
      uAmplitude: amplitude,
      uSpeed: speed,
      uSoftness: softness,
      uDetail: DETAIL,
    },
    name: 'gradient-waves',
    degrade: (quality) => ({
      uDetail: quality === 'low' ? LOW_DETAIL : DETAIL,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
